// World geometry for worldmap.js (generated file - do not edit by hand).
//
// Source: Natural Earth 1:50m land + admin-0 countries (public domain), as distributed by the
// `world-atlas` npm package (land-50m.json / countries-50m.json, topojson).
//
// Generation (offline Node script, not part of the repo):
//  * LAND: land-50m polygons were unwrapped across the antimeridian, closed through the south pole for
//    Antarctica, and scan-line filled (even-odd, pixel-centre rule) into a 4096x2048 equirectangular
//    1-bit mask (0.088 deg/px). Each row is stored as alternating ocean/land run lengths
//    (LEB128 varints, row always starts with an ocean run, runs of a row sum to w); whole stream is base64.
//  * BORDERS: interior country borders (topojson mesh, arcs shared by two countries), Douglas-Peucker
//    simplified (eps 0.01 deg), quantised to 1/100 deg and stored as: varint nLines, then per line
//    varint nPoints followed by zig-zag varint (dLon, dLat) pairs (first point relative to 0,0); base64.

export const LAND = { w: 4096, h: 2048, rle: '' };

export const BORDERS = { scale: 100, data: '' };
